sys_script_include.script:
function FixTechnicalUser(vUser)
{
	var grUser = GetUserRecord(vUser);
	if (IsValidRecord(grUser) == false)
	{
		return false;
	}
	if (IsTechnicalUser(grUser) == true)
	{
		return true;
	}

	if (IsPotentialTechnicalUser(grUser) == false)
	{
		return false;
	}

	if (grUser.identity_type != 'machine')
	{
		grUser.identity_type = 'machine';
	}

	if (grUser.internal_integration_user == false && grUser.web_service_access_only == false)
	{
		grUser.web_service_access_only = true;
	}

	var strUserName = GetStringValue(grUser.user_name)
	if (strUserName.startsWith('technical.') == false)
	{
		grUser.first_name = 'technical.' + strUserName;
	}

	if (grUser.first_name != 'Technical')
	{
		if (grUser.first_name != '')
		{
			grUser.last_name = grUser.first_name + ' ' + grUser.last_name;
		}
		grUser.first_name = 'Technical';
	}

	GlideRecordUpdate(grUser);
	return IsTechnicalUser(grUser.sys_id);

/*
if (current.internal_integration_user == true)
	{
		bPotential = true;
	}
	if (current.web_service_access_only == true)
	{
		bPotential = true;
	}
	if (current.identity_type == 'machine')
	{
		bPotential = true;
	}
	var strUserName = x_snc_devtools.GetStringValue(current.user_name);
	if (strUserName.startsWith('technical.') == true)
	{
